module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

parameter PIPE_STAGES = 4;

reg [size-1:0] mul_a_reg;
reg [size-1:0] mul_b_reg;
reg [size*2-1:0] temp [PIPE_STAGES];
reg [size*2-1:0] sum [PIPE_STAGES];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out <= 0;
        mul_out <= 0;
        mul_a_reg <= 0;
        mul_b_reg <= 0;
        temp[0] <= 0;
        sum[0] <= 0;
        for (int i = 1; i < PIPE_STAGES; i++) begin
            temp[i] <= 0;
            sum[i] <= 0;
        end
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            for (int i = 0; i < size; i++) begin
                temp[i] <= mul_a_reg * mul_b_reg[i];
            end
            for (int i = 0; i < PIPE_STAGES - 1; i++) begin
                sum[i+1] <= sum[i] + temp[i];
            end
            mul_en_out <= mul_en_in;
            mul_out <= sum[PIPE_STAGES-1];
        end else begin
            mul_en_out <= 0;
        end
    end
end

endmodule
